// In-process log-stream reads (#3630) — the perf-critical replacement for polling the unified log
// streams through the `bsc` bridge, which SPAWNED a `bsc.exe` subprocess per read (`console::bsc`).
// The always-on fleet/console pumps (`useCoordLog`, `useWorkerAutoEnd`, the pane-activity poll) hit
// these every ~1s; at 5–10 spawns/sec the Tauri invoke backlog grew without bound and the app froze.
// These native commands (`observability::logs::logs_*`) read the SAME files in-process via the `logs`
// crate — a file read, not a process — so the hot polls stop saturating the backend.
//
// Same JSON shape the `bsc logs …` subcommands emitted (the native commands return the same serde
// types), so these are drop-ins for the prior `bscJson(null, ["logs", …])` calls. Low-frequency
// `bsc logs …` reads (cost, analytics one-shots) stay on the `bsc` bridge.

import { safeInvoke } from "@/shared/lib/core/safeInvoke";

/** One pane's latest turn-boundary state — the `logs::PaneActivity` shape (`bsc logs pane-activity`). */
export interface PaneActivityRow {
  pane: string;
  state: string;
  at: number;
}

/**
 * Newest `limit` raw lines of a unified log stream (`coord`/`audit`/`skill`/`hook`/`mcp`/`ui`/…),
 * read in-process. `oldest` keeps chronological (oldest-first) order — pass `true` for the coord/ui
 * logs the replayers walk forward. An unknown/missing stream resolves to `fallback` (default `[]`);
 * pass `null` where a caller must distinguish "read failed → skip this tick" from an empty log.
 */
export function logsTail(stream: string, limit: number, oldest?: boolean): Promise<string[]>;
export function logsTail<F>(stream: string, limit: number, oldest: boolean, fallback: F): Promise<string[] | F>;
export function logsTail(stream: string, limit: number, oldest = false, fallback: unknown = []): Promise<unknown> {
  return safeInvoke("logs_tail", { stream, limit, oldest }, fallback);
}

/** The latest turn-boundary state per pane (`run`/`idle`), newest pane first — `bsc logs pane-activity`.
 *  Generic `T` lets a caller keep its own row type; the wire shape is always `{ pane, state, at }`. */
export function logsPaneActivity<T = PaneActivityRow>(): Promise<T[]> {
  return safeInvoke<T[]>("logs_pane_activity", undefined, []);
}

/** The deduped set of panes that self-reported `done` (#1379), newest first — `bsc logs done-panes`. */
export function logsDonePanes(): Promise<string[]> {
  return safeInvoke<string[]>("logs_done_panes", undefined, []);
}

/** One blocked session — the `logs::WaitingSession` shape (`bsc logs waiting`). */
export interface WaitingRow {
  /** The pane/session that is blocked. */
  pane: string;
  /** `wait` · `ask` · `request` · `permission` — what kind of answer it needs. */
  kind: string;
  /** The question / reason / request text. EMPTY for a permission prompt, which carries none. */
  detail: string;
  /** Epoch-ms of the opening event. */
  at: number;
  /** The request id, for `kind: "request"` — what `bsc plan request resolve` takes. Else empty. */
  id: string;
}

/**
 * Every session blocked on a HUMAN, OLDEST FIRST — `bsc logs waiting` (#4015).
 *
 * Oldest-first is the contract, not a default: this is a QUEUE and the longest-waiting session is
 * the one to clear first. Do not re-sort it newest-first to match the other feeds.
 *
 * Deliberately NOT computed from `coordinationLog.ts`, which reduces the same coord.log in the
 * frontend. `waiting.rs` says the two MUST agree and that the DIRECTOR is what suffers when they
 * do not — its protocol tells it to run `bsc logs waiting` and drive the queue to empty. Rendering
 * the reducer would put a human in front of a different queue than the director works.
 */
export function logsWaiting(): Promise<WaitingRow[]> {
  return safeInvoke<WaitingRow[]>("logs_waiting", undefined, []);
}

/** One session's whole footprint — the `logs::SessionRow` shape (`bsc logs sessions`). */
export interface SessionRollupRow {
  /** The pane/session id. */
  session: string;
  /** Derived from the id: worker · planner · director · session. */
  role: string;
  /** Tool attempts recorded for it (the audit stream). */
  tools: number;
  /** Skill invocations. */
  skills: number;
  /** MCP calls. Legacy column-less lines stay unattributed and count toward NO session. */
  mcp: number;
  /** Coordination events emitted. */
  coord: number;
  /** Cost in USD, from the session transcript.
   *
   *  SNAKE_CASE ON PURPOSE. `SessionRow` has no `serde(rename_all)`, unlike `WaitingSession` right
   *  above it, so this field crosses the wire as `cost_usd` — and the SAME struct is what
   *  `bsc logs sessions --json` prints, so camelCasing the Rust side to make TypeScript prettier
   *  would change a CLI contract. A mismatch here does not throw: the field reads `undefined` and
   *  every row renders $0.00, which looks like a fleet that cost nothing. */
  cost_usd: number;
  /** Latest activity state (`run`/`idle`/`attn`), or EMPTY when the session never reported one. */
  activity: string;
}

/**
 * The per-session rollup across every pane-tagged stream plus cost — `bsc logs sessions` (#1607).
 *
 * The heaviest log read in the app: five streams plus the cost rollup, which re-reads every
 * transcript named in `tokens.log`. Poll it only while something is showing it.
 */
export function logsSessions(): Promise<SessionRollupRow[]> {
  return safeInvoke<SessionRollupRow[]>("logs_sessions", undefined, []);
}

/** One session's token + cost rollup — the `logs::Cost` shape (`bsc logs cost`).
 *
 *  SNAKE_CASE, like `SessionRollupRow` and for the same reason: `Cost` carries no
 *  `serde(rename_all)`, and the same struct is what `bsc logs cost --json` prints. */
export interface CostRow {
  session: string;
  /** The model the transcript reports. `<synthetic>` for a message with no real model. */
  model: string;
  input: number;
  output: number;
  cache_creation: number;
  cache_read: number;
  cost_usd: number;
}

/** The whole fleet's token + cost rollup — `bsc logs cost` (#1607). Re-reads every transcript
 *  named in `tokens.log`, so poll it only while something is showing it. */
export function logsCosts(): Promise<CostRow[]> {
  return safeInvoke<CostRow[]>("logs_costs", undefined, []);
}

/**
 * The canonical stream key for a read alias — mirrors Rust `logs::canonical_stream`. The UI reads a few
 * streams by alias (`audit`→`tool`, `skills`→`skill`); everything else is already canonical. Used to
 * line a read alias up with the backend's `logs://<canonical>` change event (#3638), so a subscriber
 * never misses an emit because it named the stream differently than the watcher did.
 */
export function canonicalStream(alias: string): string {
  switch (alias) {
    case "audit":
    case "tools":
      return "tool";
    case "skills":
      return "skill";
    default:
      return alias;
  }
}

/** The Tauri event the backend log watcher (`observability::log_watch`) emits when `stream` changes —
 *  the event `useLogStream` subscribes to. Accepts a read alias (canonicalized). MUST stay in sync with
 *  the Rust `event_name` (#3638). */
export function logEventName(stream: string): string {
  return `logs://${canonicalStream(stream)}`;
}

